    const WEIGHTS={personalized:.48,objective:.10,budget:.08,runnerWeight:.03,distance:.09,terrain:.10,foot:.03,strike:.02,brand:.02,foulee:.05};
    const COEFS=[1.5,1.25,1.1];
    const OBJ={
    "ENTRAÎNEMENT":{"DAILY":100,"TEMPO":75,"MAX CUSHION":90,"RACE":35,"POLYVALENTE":95,"ULTRA":85},
    "CONFORT":{"DAILY":90,"TEMPO":65,"MAX CUSHION":100,"RACE":30,"POLYVALENTE":85,"ULTRA":100},
    "POLYVALENT":{"DAILY":95,"TEMPO":100,"MAX CUSHION":75,"RACE":70,"POLYVALENTE":100,"ULTRA":85},
    "PERFORMANCE":{"DAILY":70,"TEMPO":100,"MAX CUSHION":50,"RACE":95,"POLYVALENTE":85,"ULTRA":80},
    "COMPÉTITION":{"DAILY":40,"TEMPO":80,"MAX CUSHION":25,"RACE":100,"POLYVALENTE":70,"ULTRA":85}
    };
    const DM={
    "< 10 KM":{"< 10 KM":100,"10 - 30 KM":70,"30 - 50 KM":30,"> 50 KM":10,"ULTRA":0},
    "10 - 30 KM":{"< 10 KM":70,"10 - 30 KM":100,"30 - 50 KM":70,"> 50 KM":30,"ULTRA":10},
    "30 - 50 KM":{"< 10 KM":30,"10 - 30 KM":70,"30 - 50 KM":100,"> 50 KM":70,"ULTRA":40},
    "> 50 KM":{"< 10 KM":10,"10 - 30 KM":30,"30 - 50 KM":70,"> 50 KM":100,"ULTRA":90},
    "ULTRA":{"< 10 KM":0,"10 - 30 KM":10,"30 - 50 KM":40,"> 50 KM":90,"ULTRA":100}
    };
    const TM={
    "ROULANT":{"ROULANT":100,"MIXTE":75,"TECHNIQUE":35,"MONTAGNE":15,"TOUTES":90},
    "MIXTE":{"ROULANT":75,"MIXTE":100,"TECHNIQUE":80,"MONTAGNE":55,"TOUTES":90},
    "TECHNIQUE":{"ROULANT":35,"MIXTE":80,"TECHNIQUE":100,"MONTAGNE":85,"TOUTES":90},
    "MONTAGNE":{"ROULANT":15,"MIXTE":55,"TECHNIQUE":85,"MONTAGNE":100,"TOUTES":90},
    "TOUTES":{"ROULANT":90,"MIXTE":90,"TECHNIQUE":90,"MONTAGNE":90,"TOUTES":100}
    };
    const CR=[["ACCROCHE","accroche"],["AMORTI","amorti"],["STABILITE","stabilite"],["PROTECTION","protection"],["DYNAMISME","dynamisme"],["CONFORT","confort"]];
    const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
    const norm=s=>String(s??"").toUpperCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"");

    $$(".question").forEach(q=>$$(".option",q).forEach(b=>b.onclick=()=>{$$(".option",q).forEach(x=>x.classList.remove("selected"));b.classList.add("selected")}));
    const selected=k=>{const q=$(`.question[data-key="${k}"]`),b=q&&$(".selected",q);return b?b.dataset.value:""};
    const profile=()=>({budget:+$("#budget").value,objectif:selected("objectif"),distance:selected("distance"),terrain:selected("terrain"),poids:+$("#poids").value,typePied:selected("typePied"),attaque:selected("attaque"),foulee:selected("foulee"),pointure:+$("#pointure").value,rayon:selected("rayon"),priorite1:selected("priorite1"),priorite2:selected("priorite2"),priorite3:selected("priorite3"),marque:selected("marque")});
    function validate(p){if(!p.budget||!p.objectif||!p.distance||!p.terrain||!p.poids||!p.typePied||!p.attaque||!p.foulee||!p.pointure||!p.rayon||!p.priorite1||!p.priorite2||!p.priorite3||!p.marque)return"Merci de compléter toutes les informations.";if(new Set([p.priorite1,p.priorite2,p.priorite3]).size<3)return"Les 3 priorités doivent être différentes.";if(p.pointure<35||p.pointure>50||Math.abs(p.pointure*2-Math.round(p.pointure*2))>0.001)return"Entre une pointure comprise entre 35 et 50, par demi-pointure.";return""}
    function personalized(s,p){let n=0,d=0;const ps=[p.priorite1,p.priorite2,p.priorite3];CR.forEach(([c,k])=>{let co=1,idx=ps.indexOf(c);if(idx>=0)co=COEFS[idx];n+=s[k]*co;d+=co});return 10*n/d}
    function budget(s,p){let d=s.prix-p.budget;return d<=0?100:d<=10?90:d<=20?75:d<=30?55:d<=50?30:0}
    function weight(s,p){if(p.poids>s.poidsMax)return 0;if(p.poids>=s.poidsIdealMin&&p.poids<=s.poidsIdealMax)return 100;let d=Math.min(Math.abs(p.poids-s.poidsIdealMin),Math.abs(p.poids-s.poidsIdealMax));return d<=5?90:d<=10?70:d<=15?40:0}
    function tokensDistance(raw){let s=norm(raw),o=[];["< 10 KM","10 - 30 KM","30 - 50 KM","> 50 KM","ULTRA"].forEach(x=>{if(s.includes(norm(x)))o.push(x)});if(/10\s*-\s*50\s*KM/.test(s))o.push("10 - 30 KM","30 - 50 KM");if(/10\s*-\s*(80|100)\s*KM/.test(s))o.push("10 - 30 KM","30 - 50 KM","> 50 KM");if(/30\s*-\s*100\s*KM/.test(s))o.push("30 - 50 KM","> 50 KM","ULTRA");return[...new Set(o)]}
    function distance(s,p){let t=tokensDistance(s.distance);return t.length?Math.max(...t.map(x=>DM[p.distance]?.[x]||0)):0}
    function terrain(s,p){let st=norm(s.terrain),vals=[];["ROULANT","MIXTE","TECHNIQUE","MONTAGNE","TOUTES"].forEach(x=>{if(st.includes(norm(x)))vals.push(TM[p.terrain]?.[x]||0)});if(st.includes("BOUE"))vals.push(TM[p.terrain]?.["TECHNIQUE"]||0);return vals.length?Math.max(...vals):0}
    function foot(s,p){return norm(s.typePied).includes(norm(p.typePied))?100:50}
    function strike(s,p){if(p.attaque==="JE NE SAIS PAS")return 100;let needle=p.attaque==="AVANT-PIED"?"AVANT":(p.attaque==="MÉDIO-PIED"?"MILIEU":p.attaque);return norm(s.attaque).includes(norm(needle))?100:50}
    // Foulée : les chaussures de trail sont presque toutes neutres ; pour un pied qui s'affaisse vers l'intérieur (pronation),
    // les chaussures de stabilité puis les neutres les plus stables passent devant.
    function foulee(s,p){const st=s.foulee==="STABILITÉ";if(p.foulee==="PRONATION")return st?100:Math.max(0,Math.min(100,(s.stabilite-7)*100/3));if(p.foulee==="NEUTRE")return st?60:100;if(p.foulee==="SUPINATION")return st?30:100;return 100}
    function brand(s,p){return p.marque==="AUCUNE"?100:(s.marque===p.marque?100:50)}
    function calc(s,p){let sc={personalized:personalized(s,p),objective:OBJ[p.objectif]?.[s.type]||0,budget:budget(s,p),runnerWeight:weight(s,p),distance:distance(s,p),terrain:terrain(s,p),foot:foot(s,p),strike:strike(s,p),brand:brand(s,p),foulee:foulee(s,p)};let final=Object.keys(WEIGHTS).reduce((a,k)=>a+sc[k]*WEIGHTS[k],0);return{...s,sc,final,eligible:p.poids<=s.poidsMax}}
