    function strengths(s){return CR.map(([l,k])=>[l,s[k]]).sort((a,b)=>b[1]-a[1]).slice(0,3).map(x=>pretty(x[0])).join(" · ")}
    function weak(s){let x=CR.map(([l,k])=>[l,s[k]]).sort((a,b)=>a[1]-b[1])[0];return x[1]<7?pretty(x[0]):""}
