    // Liens Kwanko enregistrés sous forme courte (ir:, es:, ek:) : les robots qui lisent ce fichier
    // n'y trouvent aucune adresse à cliquer. Les adresses complètes sont reconstruites ici, en mémoire.
    const KWANKO_HOSTS=Object.fromEntries(Object.entries({ir:"rf.nur-i.xsf",es:"rf.erots-ecnarudne.foz",ek:"rf.tropsoke.azi"}).map(([k,h])=>[k,[...h].reverse().join("")]));
    function kwankoLink(v){
      const m=/^(ir|es|ek):(.+)$/.exec(v||"");
      return m?"https://"+KWANKO_HOSTS[m[1]]+"/?"+m[2]:v;
    }
    function isKwankoLink(href){
      return Object.values(KWANKO_HOSTS).some(h=>href.includes(h));
    }
    SHOES.forEach(s=>["lien","lienIRun"].forEach(k=>{if(s[k])s[k]=kwankoLink(s[k]);}));
    Object.values(MERCHANT_OFFERS).forEach(list=>list.forEach(o=>{if(o.link)o.link=kwankoLink(o.link);}));

    function normalizeRayon(v){
      v=(v||"").toString().toLowerCase();
      if(v.includes("femme")) return "female";
      if(v.includes("homme")) return "male";
      return "any";
    }
    function offerGenderOk(o,p){
      const r=normalizeRayon(p.rayon);
      return r==="any" || o.gender==="unisex" || o.gender===r;
    }
    function sizeDistance(o,target){
      if(!Number.isFinite(target)||!o.sizes?.length) return 99;
      return Math.min(...o.sizes.map(s=>Math.abs(Number(s)-target)));
    }
    function bestOfferVariant(group,target){
      return [...group].sort((a,b)=>{
        const da=sizeDistance(a,target),db=sizeDistance(b,target);
        if(da!==db)return da-db;
        return a.price-b.price;
      })[0];
    }
    function merchantFallbackPriority(key){
      if(key==="i-run") return 0;
      if(key==="decathlon") return 1;
      return 2;
    }
    function selectedMerchantOffers(shoe,p){
      const target=Number(p.pointure);
      const raw=(MERCHANT_OFFERS[shoe.modele]||[]).filter(o=>offerGenderOk(o,p));
      const byMerchant={};
      raw.forEach(o=>(byMerchant[o.key]??=[]).push(o));
      let offers=Object.values(byMerchant).map(g=>bestOfferVariant(g,target)).filter(Boolean);

      // Priorité marchands MYBESTPAIR :
      // 1) pointure exacte disponible ; 2) taille à +/- 0,5 ; 3) meilleur prix ;
      // 4) si aucune disponibilité exploitable ET aucun prix : I-RUN puis Decathlon.
      const exact=offers.filter(o=>o.sizes?.length && sizeDistance(o,target)<0.001);
      const half=offers.filter(o=>o.sizes?.length && sizeDistance(o,target)>0.001 && sizeDistance(o,target)<=0.5001);
      let ranked;
      if(exact.length){
        ranked=[...exact].sort((a,b)=>a.price-b.price || merchantFallbackPriority(a.key)-merchantFallbackPriority(b.key));
        ranked.push(...offers.filter(o=>!exact.includes(o)).sort((a,b)=>{
          const da=sizeDistance(a,target), db=sizeDistance(b,target);
          const aHalf=da<=0.5001?0:1, bHalf=db<=0.5001?0:1;
          if(aHalf!==bHalf)return aHalf-bHalf;
          return a.price-b.price || merchantFallbackPriority(a.key)-merchantFallbackPriority(b.key);
        }));
      }else if(half.length){
        ranked=[...half].sort((a,b)=>a.price-b.price || sizeDistance(a,target)-sizeDistance(b,target) || merchantFallbackPriority(a.key)-merchantFallbackPriority(b.key));
        ranked.push(...offers.filter(o=>!half.includes(o)).sort((a,b)=>a.price-b.price || merchantFallbackPriority(a.key)-merchantFallbackPriority(b.key)));
      }else{
        // Personne n'a la pointure exacte ou une taille à +/-0,5 : le prix décide.
        ranked=[...offers].sort((a,b)=>{
          const ap=Number.isFinite(Number(a.price)), bp=Number.isFinite(Number(b.price));
          if(ap!==bp)return ap?-1:1;
          if(ap && Number(a.price)!==Number(b.price))return Number(a.price)-Number(b.price);
          return merchantFallbackPriority(a.key)-merchantFallbackPriority(b.key);
        });
      }

      // Liens historiques uniquement en dernier recours quand le flux ne permet pas de départager.
      const legacy=[];
      if(shoe.lienIRun) legacy.push({merchant:"I-RUN",key:"i-run",link:shoe.lienIRun,price:null,sizes:[],gender:'unisex',legacy:true});
      if(shoe.lien){const m=merchantInfo(shoe.lien);legacy.push({merchant:m.name,key:m.key,link:shoe.lien,price:null,sizes:[],gender:'unisex',legacy:true});}
      const used=new Set();
      const result=[];
      for(const o of ranked){ if(!used.has(o.key)){result.push(o);used.add(o.key);} if(result.length===2)break; }
      if(result.length<2){
        legacy.sort((a,b)=>merchantFallbackPriority(a.key)-merchantFallbackPriority(b.key));
        for(const o of legacy){if(!used.has(o.key)){result.push(o);used.add(o.key);} if(result.length===2)break;}
      }
      return result;
    }
    // Affiche 40.67 / 41.33 (pointures en tiers du catalogue i-Run) en « 40 2/3 » / « 41 1/3 ».
    function sizeLabel(s){
      const n=Number(s),i=Math.floor(n),f=Math.round((n-i)*100);
      if(f===33)return `${i} 1/3`;
      if(f===67)return `${i} 2/3`;
      return String(n).replace('.',',');
    }
    function formatSizes(o,target){
      if(!o.sizes?.length)return "Pointures à vérifier";
      const sizes=[...new Set(o.sizes.map(Number))].sort((a,b)=>a-b);
      const exact=sizes.some(s=>Math.abs(s-target)<0.001);
      if(exact) return `✓ Ta pointure ${String(target).replace('.',',')} est disponible`;
      const near=sizes.filter(s=>Math.abs(s-target)<=0.5001);
      const shown=(near.length?near:sizes.slice(0,5)).map(sizeLabel);
      return `${shown.length>1?'Pointures proches disponibles':'Pointure proche disponible'} : ${shown.join(' · ')}`;
    }
    function smartMerchantHTML(shoe,p,rank){
      const offers=selectedMerchantOffers(shoe,p), target=Number(p.pointure);
      if(!offers.length)return `${merchantLink(shoe.lien,shoe,rank)}${shoe.lienIRun?merchantLink(shoe.lienIRun,shoe,rank,"irun"):""}`;
      return offers.map((o,i)=>{
        const price=o.price!=null?`<strong>${o.price.toFixed(2).replace('.',',')} €</strong> · `:"";
        const label=i===0?"OFFRE PRINCIPALE":"AUTRE REVENDEUR";
        const size=o.legacy?"Disponibilité à vérifier":formatSizes(o,target);
        return `<div class="smart-offer"><div class="smart-offer-label">${label}</div><div class="smart-offer-meta">${price}${o.merchant} · ${size}</div>${merchantLink(o.link,shoe,rank,o.key)}</div>`;
      }).join("");
    }

    function merchantInfo(url){
      const u=(url||"").toLowerCase();
      if(u.includes("click.linksynergy.com") || u.includes("decathlon.fr")) return {name:"DECATHLON",key:"decathlon",icon:"cart"};
      if(u.includes("endurance-store.fr")) return {name:"ENDURANCE-STORE",key:"endurance-store",icon:"cart"};
      if(u.includes("i-run.fr")) return {name:"I-RUN",key:"i-run",icon:"footprints"};
      if(u.includes("ekosport.fr")) return {name:"EKOSPORT",key:"ekosport",icon:"cart"};
      return {name:"LE REVENDEUR",key:"autre",icon:"cart"};
    }
    function merchantLink(url,shoe,rank,extraClass=""){
      if(!url)return "";
      const m=merchantInfo(url);
      return `<a class="shoe-link${extraClass?` ${extraClass}`:""}" href="${url}" target="_blank" rel="noopener noreferrer" data-product-name="${shoe.modele}" data-product-brand="${shoe.marque}" data-rank="${rank}" data-merchant="${m.key}">${mbpIcon(m.icon)} VOIR CHEZ ${m.name}</a>`;
    }

    function card(s,i,p){let m=mbpRank(i+1),w=weak(s);return`<article class="shoe-card rank-${i+1}"><div class="rank-head"><span class="with-ico">${m} ${i===0?"TA RECOMMANDATION":`${i+1}e RECOMMANDATION`}</span><span class="with-ico">${mbpIcon("star","ico-gold")} ${Math.round(s.final)} / 100</span></div><div class="shoe-body"><h3 class="shoe-name">${s.modele}</h3><div class="brand-line">${s.marque} • ${s.type}</div><div class="score-line"><strong>Score MYBESTPAIR</strong><span class="score-big">${Math.round(s.final)}/100</span></div><div class="meta"><span class="pill">${mbpIcon("euro")} ${Math.round(s.prix)} €</span><span class="pill">${budgetLabel(s,p)}</span><span class="pill">${mbpIcon("scale")} ${Math.round(s.poidsChaussure)} g</span><span class="pill">${mbpIcon("ruler")} ${s.distance}</span><span class="pill">${mbpIcon("mountain")} ${s.terrain}</span></div><div class="detail"><strong>${mbpIcon("check","ico-ok")} POINTS FORTS :</strong> ${strengths(s)}</div>${w?`<div class="detail"><strong>${mbpIcon("alert","ico-warn")} POINT À SAVOIR :</strong> ${w}</div>`:""}<div class="detail"><strong>${mbpIcon("target","ico-info")} TES PRIORITÉS :</strong> ${pretty(p.priorite1)} · ${pretty(p.priorite2)} · ${pretty(p.priorite3)}</div><div class="detail"><strong>${mbpIcon("bulb","ico-gold")} Pourquoi cette chaussure ?</strong><br>${why(s,p)}</div><div class="merchant-label">${mbpIcon("cart")} Où trouver cette chaussure ?</div><div class="merchant-offers">${smartMerchantHTML(s,p,i+1)}</div></div></article>`}
    function show(p){
    let r=SHOES.map(s=>calc(s,p)).filter(s=>s.eligible).sort((a,b)=>b.final-a.final);
    let top3=r.slice(0,3);
    $("#podium").innerHTML=top3.map((s,i)=>card(s,i,p)).join("");
    $("#resultsSub").textContent=`${r.length} modèles compatibles analysés sur 51 références Trail.`;
    $("#results").style.display="block";
    if(typeof gtag==="function"){
    gtag("event","recommendation_generated",{
    sport:"trail",
    compatible_models:r.length,
    top_1:top3[0]?.modele||"",
    top_2:top3[1]?.modele||"",
    top_3:top3[2]?.modele||""
    });
    }
    $("#results").scrollIntoView({behavior:"smooth"})
    }

    let trailQuestionnaireStarted=false;
    function trackTrailQuestionnaireStart(){
    if(trailQuestionnaireStarted)return;
    trailQuestionnaireStarted=true;
    if(typeof gtag==="function")gtag("event","questionnaire_start",{sport:"trail"});
    }
    $("#questionnaire").addEventListener("click",e=>{
    if(e.target.closest(".option"))trackTrailQuestionnaireStart();
    });
    $("#questionnaire").addEventListener("input",e=>{
    if(e.target.matches("input"))trackTrailQuestionnaireStart();
    });
    $("#podium").addEventListener("click",e=>{
    const link=e.target.closest(".shoe-link");
    if(!link)return;
    const productName=link.dataset.productName||"";
    const productBrand=link.dataset.productBrand||"";
    const rank=Number(link.dataset.rank||0);
    const href=link.href||"";
    const merchant=link.dataset.merchant||"";
    const isRakuten=href.includes("click.linksynergy.com");
    const isAwin=href.includes("awin1.com");
    const isKwanko=isKwankoLink(href)||href.includes("kwanko.com");
    const isAffiliate=isRakuten||isAwin||isKwanko;
    const affiliateNetwork=isKwanko?"kwanko":(isRakuten?"rakuten":(isAwin?"awin":""));
    if(typeof gtag==="function"){
    gtag("event","product_click",{
    product_name:productName,brand:productBrand,rank:rank,sport:"trail",
    affiliate:isAffiliate?"yes":"no",merchant:merchant
    });
    if(isAffiliate){
    gtag("event","affiliate_click",{
    product_name:productName,brand:productBrand,rank:rank,sport:"trail",
    affiliate_network:affiliateNetwork,merchant:merchant
    });
    }
    }
    });
    $("#recommendBtn").onclick=()=>{let p=profile(),e=validate(p);if(e){$("#errorBox").innerHTML=mbpIcon("alert")+" ";$("#errorBox").append(e);$("#errorBox").style.display="block";return}$("#errorBox").style.display="none";mbpLoader({steps:["Analyse de ton profil de traileur","Comparaison des 51 modèles Trail","Calcul de ton Top 3"]},()=>show(p))};
    $("#restartBtn").onclick=()=>{$("#results").style.display="none";$("#questionnaire").scrollIntoView({behavior:"smooth"})};
